 @SubscribeEvent public void frame(TickEvent.RenderTickEvent e){if(e.phase!=TickEvent.Phase.START)return;if(phase==7||phase==8){Minecraft view=Minecraft.getMinecraft();if(view.thePlayer!=null&&view.thePlayer.ridingEntity instanceof EntityRollingStock){view.thePlayer.rotationYaw=view.thePlayer.prevRotationYaw=((EntityRollingStock)view.thePlayer.ridingEntity).rotationYaw;view.thePlayer.rotationPitch=view.thePlayer.prevRotationPitch=8;}return;}if(phase!=2||!ready||index>=6)return;Minecraft mc=Minecraft.getMinecraft();if(mc.thePlayer==null)return;EntityRollingStock stock=trains[index];double x=stock.posX+24,y=stock.posY+12,z=stock.posZ+24;mc.thePlayer.setPositionAndRotation(x,y,z,135,18);mc.thePlayer.prevPosX=mc.thePlayer.lastTickPosX=x;mc.thePlayer.prevPosY=mc.thePlayer.lastTickPosY=y;mc.thePlayer.prevPosZ=mc.thePlayer.lastTickPosZ=z;mc.thePlayer.prevRotationYaw=135;mc.thePlayer.prevRotationPitch=18;}private static void check(boolean b,String s){if(!b)throw new AssertionError(s);}private void pass(String s){report.add("PASS: "+s);}private static EntityPlayerMP player(){return(EntityPlayerMP)MinecraftServer.getServer().getConfigurationManager().playerEntityList.get(0);}private static WorldServer world(){return(WorldServer)player().worldObj;}private void server(Runnable r){ServerWork.enqueue(()->{try{r.run();}catch(Throwable e){failed=true;report.add("FAIL: server "+e);IndustrialTechnology.log.error("Rail QA",e);}});}private void shot(Minecraft mc,String name){report.add("VIEW: "+name+" pos="+mc.thePlayer.posX+","+mc.thePlayer.posY+","+mc.thePlayer.posZ+" yaw="+mc.thePlayer.rotationYaw+" pitch="+mc.thePlayer.rotationPitch+" time="+mc.theWorld.getWorldTime());ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());try{Files.write(new File(mc.mcDataDir,"rail-client-progress.txt").toPath(),report,StandardCharsets.UTF_8);}catch(Exception ignored){}}
