 @SubscribeEvent public void tick(TickEvent.ClientTickEvent event){if(done||event.phase!=TickEvent.Phase.END||--wait>0)return;Minecraft mc=Minecraft.getMinecraft();try{if(failed){finish();return;}if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)){wait=20;return;}mc.gameSettings.guiScale=3;mc.gameSettings.renderDistanceChunks=5;mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;WorldSettings s=new WorldSettings(92,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT);s.func_82750_a("2;7,70x0,1;1;");mc.launchIntegratedServer("rail-client","Disposable solar railway QA",s);phase=1;wait=70;return;}if(mc.thePlayer==null||mc.theWorld==null){if(++age>100)throw new AssertionError("Join timeout");wait=10;return;}
 if(phase==1){mc.displayGuiScreen(null);TooltipClientChecks.prepare(mc);server(()->{WorldServer w=world();player().capabilities.isFlying=true;player().sendPlayerAbilities();w.setWorldTime(6000);w.getGameRules().setOrCreateGameRule("doDaylightCycle","false");for(int type=0;type<6;type++){int z=type*32;for(int x=0;x<=160;x+=16){w.getChunkFromChunkCoords(x>>4,z>>4);w.setBlock(x,72,z,RailwayRegistry.anchor,0,3);TileTrack t=(TileTrack)w.getTileEntity(x,72,z);t.shape=0;t.facing=0;TrackWorld.remove(t);TrackWorld.add(t);w.markBlockForUpdate(x,72,z);}for(int x=32;x<116;x++)for(int dz=-2;dz<=2;dz++)w.setBlock(x,71,z+dz,Blocks.stone,0,3);TileTrack t=(TileTrack)w.getTileEntity(64,72,z);trains[type]=new EntityRollingStock(w,StockType.safe(type),new TrackWorld.Cursor(t.id,0,8,1),player().getUniqueID());w.spawnEntityInWorld(trains[type]);trains[type].energy=1500000;trains[type].temperature=180;trains[type].water=15000;}w.setBlock(76,72,67,RailwayRegistry.stations[0],0,3);for(int i=0;i<5;i++){for(int dx=0;dx<3;dx++)w.setBlock(56+i*4+dx,72,16,RailwayRegistry.solar[i],0,3);}for(int i=0;i<5;i++)trains[0].fuel.insert(0,new ItemStack(Items.coal,64),64,false);for(int i=0;i<5;i++)trains[4].cargo.insert(0,new ItemStack(Items.coal,64),64,false);for(int i=0;i<2;i++)trains[4].cargo.insert(1,new ItemStack(Blocks.stone,64),64,false);trains[4].cargo.insert(2,new ItemStack(Items.iron_ingot,67),67,false);camera(trains[0]);ready=true;});phase=2;wait=90;return;}
 if(phase==2){if(!ready){wait=10;return;}net.minecraft.entity.Entity seen=mc.theWorld.getEntityByID(trains[index].getEntityId());if(!(seen instanceof EntityRollingStock)){if(++age>100)throw new AssertionError("Train entity not synchronized: "+index);final int which=index;server(()->{trains[which]=loaded(trains[which]);camera(trains[which]);});wait=10;return;}age=0;check(GL11.glGetError()==GL11.GL_NO_ERROR,"model GL");shot(mc,"rail-model-"+index+".png");pass("Native model, wheels and track render: "+StockType.safe(index).title);if(++index<6){server(()->{trains[index]=loaded(trains[index]);camera(trains[index]);});wait=45;return;}server(()->{player().playerNetServerHandler.setPlayerLocation(66,78,28,180,20);});phase=3;wait=40;return;}
 if(phase==3){shot(mc,"solar-five-tiers.png");check(GL11.glGetError()==GL11.GL_NO_ERROR,"solar GL");pass("All five photovoltaic tiers render with registered official cell textures");server(()->{player().playerNetServerHandler.setPlayerLocation(56,73,19,180,15);check(!player().theItemInWorldManager.activateBlockOrUseItem(player(),world(),null,56,72,16,1,.5f,.5f,.5f),"solar right-click consumed");});phase=4;wait=30;return;}
 if(phase==4){check(mc.currentScreen==null,"solar panel opened a GUI");check(IndustrialTechnology.proxy.getClientGuiElement(3,mc.thePlayer,mc.theWorld,56,72,16)==null,"retired solar GUI route");shot(mc,"solar-no-gui.png");check(GL11.glGetError()==GL11.GL_NO_ERROR,"solar interaction GL");pass("Real solar-panel right-click leaves the screen closed; retired client GUI ID is unavailable");server(()->{player().closeScreen();player().playerNetServerHandler.setPlayerLocation(72,73,133,180,0);});phase=42;wait=50;return;}
 if(phase==42){server(()->{trains[4]=loaded(trains[4]);});if(!(mc.theWorld.getEntityByID(trains[4].getEntityId()) instanceof EntityRollingStock)){wait=10;return;}server(()->player().openGui(IndustrialTechnology.instance,4,world(),trains[4].getEntityId(),0,0));phase=5;wait=30;return;}
 if(phase==5){check(mc.currentScreen instanceof GuiExpansion,"freight GUI");shot(mc,"freight-three-slots.png");GuiExpansion g=(GuiExpansion)mc.currentScreen;check(g.expansion.inventorySlots.size()==36,"fake inventory slots");pass("Freight GUI displays exactly three custom logical bins plus 36 normal player slots");IndustrialTechnology.network.sendToServer(new ExpansionCommand(g.expansion.windowId,trains[4].getEntityId(),10,2));phase=6;wait=25;return;}
 if(phase==6){server(()->check(trains[4].cargo.count(0)==236,"safe cursor extraction did not debit 64"));check(GL11.glGetError()==GL11.GL_NO_ERROR,"cargo click GL");pass("Actual client request extracts a valid 64-item coal stack from 300 logical coal");server(()->{player().closeScreen();camera(trains[2]);});phase=62;wait=50;return;}
 if(phase==62){server(()->{trains[2]=loaded(trains[2]);check(world().getEntityByID(trains[2].getEntityId())==trains[2],"live mount target missing");if(player().ridingEntity!=trains[2])player().mountEntity(trains[2]);});phase=7;age=0;wait=30;return;}
 if(phase==7){if(!(mc.thePlayer.ridingEntity instanceof EntityRollingStock)){if(++age>60)throw new AssertionError("mount sync");wait=10;return;}shot(mc,"acs64-cab.png");pass("Driver mount and first-person cab synchronize to the client");mc.gameSettings.thirdPersonView=1;phase=70;wait=25;return;}
 if(phase==70){shot(mc,"acs64-third-person.png");pass("Third-person camera extends outside the long locomotive and keeps vanilla wall clipping");mc.gameSettings.thirdPersonView=0;int id=mc.thePlayer.ridingEntity.getEntityId();IndustrialTechnology.network.sendToServer(new ExpansionCommand(-1,id,0,0));IndustrialTechnology.network.sendToServer(new ExpansionCommand(-1,id,3,0));phase=8;wait=50;return;}
 if(phase==8){check(((EntityRollingStock)mc.thePlayer.ridingEntity).speed>0,"server traction sync");shot(mc,"acs64-moving-cab.png");pass("Server-authoritative throttle updates client speed and animated wheel travel");IndustrialTechnology.network.sendToServer(new ExpansionCommand(-1,mc.thePlayer.ridingEntity.getEntityId(),2,0));IndustrialTechnology.network.sendToServer(new ExpansionCommand(-1,mc.thePlayer.ridingEntity.getEntityId(),5,0));phase=9;wait=25;return;}
 if(phase==9){check(mc.currentScreen instanceof GuiExpansion,"driver controls GUI");shot(mc,"train-controls.png");TooltipClientChecks.railway(mc,(GuiExpansion)mc.currentScreen,this::pass);check(GL11.glGetError()==GL11.GL_NO_ERROR,"controls GL");pass("Mounted controls GUI opens through validated server packet; emergency brake is active");server(()->{player().closeScreen();((TileRailStation)world().getTileEntity(76,72,67)).energy=1000000;player().openGui(IndustrialTechnology.instance,5,world(),76,72,67);});phase=91;wait=35;return;}
 if(phase==91){check(mc.currentScreen instanceof GuiExpansion,"charging GUI");shot(mc,"charging-progress.png");check(GL11.glGetError()==GL11.GL_NO_ERROR,"charging GUI GL");pass("Charging station displays the actual locomotive RF, capacity and percentage");server(()->{player().closeScreen();player().mountEntity(null);trains[5]=loaded(trains[5]);camera(trains[5]);});phase=10;wait=50;return;}
 if(phase==10){server(()->{trains[5]=loaded(trains[5]);if(player().ridingEntity!=trains[5])player().mountEntity(trains[5]);});phase=11;age=0;wait=30;return;}if(phase==11){if(!(mc.thePlayer.ridingEntity instanceof EntityRollingStock)){if(++age>60)throw new AssertionError("passenger mount sync");wait=10;return;}check(((EntityRollingStock)mc.thePlayer.ridingEntity).stock==StockType.PASSENGER,"wrong passenger vehicle");shot(mc,"passenger-interior.png");pass("Passenger coach has a separate seated interior and synchronized passenger mount");finish();}
 }catch(Throwable e){failed=true;report.add("FAIL: phase "+phase+" "+e);IndustrialTechnology.log.error("Rail client QA",e);finish();}}
 private void finish(){if(done)return;done=true;try{report.add("Failed: "+(failed?1:0));Files.write(new File(Minecraft.getMinecraft().mcDataDir,"rail-client-report.txt").toPath(),report,StandardCharsets.UTF_8);}catch(Exception e){IndustrialTechnology.log.error("Rail report",e);}Minecraft.getMinecraft().shutdown();}
